45: (() => {
46:  const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
47:  const palette={sky:'#444b48',sky2:'#65706a',sun:'#d29261',building:'#343c3a',dark:'#222a29',mid:'#515953',sand:'#887659',sand2:'#a28a63',road:'#393b36',road2:'#565448',rust:'#965b42',light:'#d7bd83',cyan:'#71b5ac'};
