64:    for(let layer=0;layer<2;layer++){
65:     const speed=layer?.42:.2,ox=(frame*speed)%960;
66:     for(let i=-1;i<9;i++){
67:      let x=i*132-ox+(layer?34:0),base=layer?203:178,w=layer?88:106;
68:      const hash=(i+11)*31+(layer*13),h=47+(hash%94);
69:      rect(x,base-h,w,h,layer?palette.building:'#404844');
70:      rect(x+8,base-h-7,w-18,7,layer?'#414744':'#555a52');
71:      // torn roof details / antennae
72:      rect(x+19,base-h-15,4,15,'#343c39');rect(x+20,base-h-21,2,7,'#b1664b');
73:      for(let wy=base-h+15;wy<base-9;wy+=17)for(let wx=x+12;wx<x+w-8;wx+=18){if(((Math.floor(wx/18)+wy+hash)%4)!==0)rect(wx,wy,5,7,(wy%3)?'#9c7951':'#60746e')}
74:      if(hash%3===0){rect(x+w-24,base-h+14,21,5,'#a95443');rect(x+w-21,base-h+11,14,3,'#da885b')}
75:      if(layer&&hash%2===0){rect(x+45,base-h-27,2,27,'#262d2c');rect(x+37,base-h-23,18,3,'#262d2c')}
76:     }
77:    }
78:    // smoky horizon
79:    rect(0,174,960,18,'#74715f');rect(0,192,960,23,'#66614f');
80:    // ground, scrub and road
81:    rect(0,210,960,120,palette.sand);rect(0,220,960,110,'#71634c');rect(0,244,960,86,palette.road);
82:    rect(0,242,960,3,'#b59868');rect(0,327,960,3,'#a58a61');
83:    for(let i=0;i<26;i++){
84:     let x=((i*73-frame*1.65)%1020+1020)%1020,y=214+(i*29%25);
85:     rect(x,y,4+(i%5),2,'#b19b6b');rect(x+9,y-3,2,4,'#423e35');
