function skillName(member){return ({Tinkerer:'REPAIR HULL',Medic:'HEAL CREW',Scavenger:'SALVAGE CACHE',Sharpshooter:'CLEAR AMBUSH'})[member.positiveTrait]}
function canUseSkill(member){if(member.health<=0||member.skillUses<=0||ended||(paused&&!camping))return false;if(member.positiveTrait==='Tinkerer')return health<100;if(member.positiveTrait==='Medic')return crew.some(person=>person.health>0&&person.health<100);return true}
function activateSkill(member){if(!canUseSkill(member))return;member.skillUses--;let message='';if(member.positiveTrait==='Tinkerer'){health=Math.min(100,health+20);message=`${member.name} repaired the hull (+20).`}else if(member.positiveTrait==='Medic'){const target=crew.filter(person=>person.health>0&&person.health<100).sort((a,b)=>a.health-b.health)[0];if(!target){member.skillUses++;return}target.health=Math.min(100,target.health+30);message=`${member.name} treated ${target.name} (+30 vitals).`}else if(member.positiveTrait==='Scavenger'){scrap+=14;message=`${member.name} salvaged a cache (+14 scrap).`}else{nextEvent+=12;message=`${member.name} cleared the road ahead. Next encounter delayed.`}$('logText').textContent=message;showToast(message);updateUI()}

