 function toggleCamp(){if(camping){camping=false;paused=false;$('status').innerHTML='▶&nbsp; EN ROUTE';document.querySelector('.scene-wrap').style.filter='';$('logText').textContent='Camp broken. The van is back on the road.';updateUI();return}if(paused||ended)return;if(food<15){showToast('NOT ENOUGH RATIONS / NEED 15 TO CAMP');return}camping=true;paused=true;food-=15;crew.forEach(member=>member.skillUses=2);$('status').innerHTML='⌂&nbsp; CAMPED';document.querySelector('.scene-wrap').style.filter='saturate(.6)';$('logText').textContent='Camp set. Crew skills restored; the van is safely stopped.';showToast('CAMP MADE / −15 RATIONS / SKILLS RESTORED');updateUI()}
 $('scavengeLaunch').onclick=startScavenge;$('campButton').onclick=toggleCamp;document.querySelectorAll('.drone-target').forEach(target=>target.onclick=()=>shootDrone(target));$('scavengeReturn').onclick=returnFromScavenge;
 function showEvent(){if(ended)return;paused=true;eventCount++;const ev=events[Math.floor(Math.random()*events.length)];pendingCrewEffect=null;const living=crew.filter(member=>member.health>0);if(living.length&&Math.random()<.58){const target=living[Math.floor(Math.random()*living.length)],healing=Math.random()<.32;pendingCrewEffect={target,amount:Math.round(rand(20,37))*(healing?1:-1)};const change=pendingCrewEffect.amount;$('crewEvent').innerHTML=`<strong>CREW UPDATE / ${target.name.toUpperCase()}</strong> — ${healing?'TREATED':'INJURED'} ${change>0?'+':''}${change} VITALS`;$('crewEvent').classList.add('show')}else{$('crewEvent').classList.remove('show');$('crewEvent').textContent=''}$('eventKicker').textContent=ev.tag;$('eventTitle').textContent=ev.title;$('eventDesc').textContent=ev.desc;$('choices').innerHTML='';const availableChoices=[...ev.choices];const special=ev.specials?.find(choice=>living.some(member=>member[choice.kind+'Trait']===choice.trait));if(special)availableChoices.push(special);availableChoices.forEach((c,i)=>{const b=document.createElement('button');b.className='choice';const isBad=Object.values(c.delta).some(n=>n<0);if(c.trait)b.classList.add('trait-special',c.kind);b.innerHTML=`<span><span class="key">[${i+1}]</span>${c.trait?`<strong>[${c.trait}]</strong> `:''}${c.text}</span><span class="delta ${isBad?'negative':''}">${c.summary}</span>`;b.onclick=()=>choose(c);$('choices').append(b)});$('eventShade').classList.add('show');$('status').innerHTML='Ⅱ&nbsp; DECISION REQUIRED';document.querySelectorAll('.scene-wrap').forEach(el=>el.style.filter='saturate(.6)')}
function choose(c){for(const [key,value] of Object.entries(c.delta)){if(key==='fuel')fuel+=value;if(key==='food')food+=value;if(key==='health')health+=value;if(key==='scrap')scrap+=value}fuel=Math.max(0,Math.min(100,fuel));food=Math.max(0,Math.min(100,food));health=Math.max(0,Math.min(100,health));let crewNote='';if(pendingCrewEffect){const {target,amount}=pendingCrewEffect;target.health=Math.max(0,Math.min(100,target.health+amount));crewNote=` ${target.name} ${amount>0?'healed':'injured'} (${amount>0?'+':''}${amount} vitals).`;showToast(`${target.name}: ${amount>0?'+'+amount:amount} VITALS`)}pendingCrewEffect=null;$('eventShade').classList.remove('show');$('crewEvent').classList.remove('show');paused=false;nextEvent=elapsed+rand(15,20);$('status').innerHTML='▶&nbsp; EN ROUTE';document.querySelectorAll('.scene-wrap').forEach(el=>el.style.filter='');$('logText').textContent=`${c.summary}.${crewNote||' The road takes its cut.'}`;if(!crewNote)showToast(c.summary);updateUI();checkEnd()}

