const threatData={Mechanical:{detail:'LOOSE PLATING / SHEARING DEBRIS',damage:10,cost:6,currency:'SCRAP',action:'PATCH THE RIG'},Bandit:{detail:'ROAD RAIDERS / SMALL ARMS',damage:12,cost:8,currency:'FUEL',action:'BURN FUEL TO EVADE'},Toxic:{detail:'ASH-CLOUD / CONTAMINATED DUST',damage:8,cost:7,currency:'SCRAP',action:'SEAL AIR INTAKE'}};
function renderBattle(){if(!battle)return;const open=battle.badges.filter(badge=>!badge.cleared),damage=open.reduce((sum,badge)=>sum+threatData[badge.type].damage,0);$('threatList').innerHTML=battle.badges.map((badge,index)=>{const data=threatData[badge.type];return `<div class="threat-badge ${badge.type.toLowerCase()} ${badge.cleared?'cleared':''}"><span class="threat-name">${badge.type.toUpperCase()} ${String(index+1).padStart(2,'0')}</span><span class="threat-detail">${data.detail}<br>HULL HIT: −${data.damage}</span><span class="threat-state">${badge.cleared?'✓ CLEARED':'● ACTIVE'}</span></div>`}).join('');const skillTools=crew.filter(member=>canUseSkill(member)&&battle.badges.some(badge=>badge.type===skillThreat(member)&&!badge.cleared)).map(member=>`<button class="clear-tool skill-tool" type="button" data-skill="${member.initial}"><span>${member.name.split(' ')[0]} · ${skillThreat(member).toUpperCase()}</span><small>${member.skillUses} USE${member.skillUses===1?'':'S'}</small></button>`);const supplyTools=battle.badges.map((badge,index)=>{const data=threatData[badge.type],afford=data.currency==='FUEL'?fuel>=data.cost:scrap>=data.cost;return `<button class="clear-tool supply-tool" type="button" data-badge="${index}" ${badge.cleared||!afford?'disabled':''}><span>${data.action}</span><small>${badge.cleared?'CLEARED':`${data.cost} ${data.currency}`}</small></button>`});$('battleTools').innerHTML=[...skillTools,...supplyTools].join('');$('battleTools').querySelectorAll('[data-skill]').forEach(button=>button.onclick=()=>{const member=crew.find(person=>person.initial===button.dataset.skill);if(member)activateSkill(member)});$('battleTools').querySelectorAll('[data-badge]').forEach(button=>button.onclick=()=>clearWithSupplies(Number(button.dataset.badge)));$('battleTotal').innerHTML=`UNCLEARED BADGES: ${open.length}<strong>EXPECTED HULL DAMAGE: −${damage}</strong>`;$('battleFeedback').textContent=battle.feedback||'Crew skills and supply actions clear matching badges. Cleared threats deal no damage.'}
function clearWithSupplies(index){if(!battle)return;const badge=battle.badges[index];if(!badge||badge.cleared)return;const data=threatData[badge.type];if(data.currency==='FUEL'){if(fuel<data.cost)return;fuel-=data.cost}else{if(scrap<data.cost)return;scrap-=data.cost}badge.cleared=true;battle.feedback=`${badge.type} threat neutralized. −${data.cost} ${data.currency}.`;$('logText').textContent=battle.feedback;renderBattle();updateUI()}
function pushThrough(){if(!battle)return;const unresolved=battle.badges.filter(badge=>!badge.cleared),damage=unresolved.reduce((sum,badge)=>sum+threatData[badge.type].damage,0);health=Math.max(0,health-damage);const result=damage?`Pushed through: ${unresolved.map(badge=>badge.type).join(', ')} dealt ${damage} hull damage.`:'All threats cleared. The van passes without damage.';$('logText').textContent=result;showToast(damage?`−${damage} HULL / ${unresolved.length} THREAT${unresolved.length===1?'':'S'} LEFT`:'CLEAN PASSAGE / NO HULL DAMAGE');battle=null;$('eventShade').classList.remove('show');$('battlePanel').classList.remove('show');$('choices').style.display='';$('eventTip').style.display='';paused=false;nextEvent=elapsed+rand(15,20);$('status').innerHTML='▶&nbsp; EN ROUTE';document.querySelector('.scene-wrap').style.filter='';updateUI();checkEnd()}
$('pushThrough').onclick=pushThrough;
function showEvent(){if(ended)return;paused=true;eventCount++;const ev=events[Math.floor(Math.random()*events.length)];pendingCrewEffect=null;battle={badges:[]};const types=['Mechanical','Bandit','Toxic'];for(let i=types.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[types[i],types[j]]=[types[j],types[i]]}battle.badges=types.slice(0,Math.random()<.55?2:3).map(type=>({type,cleared:false}));battle.feedback='';$('crewEvent').classList.remove('show');$('crewEvent').textContent='';$('eventKicker').textContent=`HAZARD BATTLE / ${Math.round(dist)} MI`;$('eventTitle').textContent=ev.title;$('eventDesc').textContent=ev.desc;$('choices').innerHTML='';$('choices').style.display='none';$('eventTip').style.display='none';$('battlePanel').classList.add('show');renderBattle();$('eventShade').classList.add('show');$('status').innerHTML='Ⅱ&nbsp; HAZARD ENGAGED';document.querySelector('.scene-wrap').style.filter='saturate(.6)';updateUI()}

