129:  function crewState(member){return member.health<=0?'dead':member.health<=35?'critical':member.health<75?'wounded':'fit'}
130:   function skillThreat(member){return ({Tinkerer:'Mechanical',Medic:'Toxic',Scavenger:'Mechanical',Sharpshooter:'Bandit'})[member.positiveTrait]}
131:   function skillName(member){if(battle)return `CLEAR ${skillThreat(member)?.toUpperCase()||'THREAT'}`;return ({Tinkerer:'REPAIR HULL',Medic:'HEAL CREW',Scavenger:'SALVAGE CACHE',Sharpshooter:'CLEAR AMBUSH'})[member.positiveTrait]}
132:   function canUseSkill(member){if(member.health<=0||member.skillUses<=0||ended)return false;if(battle)return battle.badges.some(badge=>badge.type===skillThreat(member)&&!badge.cleared);if(paused&&!camping)return false;if(member.positiveTrait==='Tinkerer')return health<100;if(member.positiveTrait==='Medic')return crew.some(person=>person.health>0&&person.health<100);return true}
133:   function activateSkill(member){if(!canUseSkill(member))return;if(battle){member.skillUses--;const badge=battle.badges.find(item=>item.type===skillThreat(member)&&!item.cleared);if(!badge){member.skillUses++;return}badge.cleared=true;const message=`${member.name} used ${member.positiveTrait} to clear ${badge.type}.`;$('battleFeedback').textContent=message;$('logText').textContent=message;renderBattle();showToast(`${badge.type.toUpperCase()} CLEARED / 1 SKILL USE`);updateUI();return}member.skillUses--;let message='';if(member.positiveTrait==='Tinkerer'){health=Math.min(100,health+20);message=`${member.name} repaired the hull (+20).`}else if(member.positiveTrait==='Medic'){const target=crew.filter(person=>person.health>0&&person.health<100).sort((a,b)=>a.health-b.health)[0];if(!target){member.skillUses++;return}target.health=Math.min(100,target.health+30);message=`${member.name} treated ${target.name} (+30 vitals).`}else if(member.positiveTrait==='Scavenger'){scrap+=14;message=`${member.name} salvaged a cache (+14 scrap).`}else{nextEvent+=12;message=`${member.name} cleared the road ahead. Next encounter delayed.`}$('logText').textContent=message;showToast(message);updateUI()}
